plt.yticks([])

for i in (range(len(canny_cont))):
    plt.scatter(canny_cont[i].flatten().reshape(len(canny_cont[i]),2)[:,0],
         canny_cont[i].flatten().reshape(len(canny_cont[i]),2)[:,1])
</textarea></div><p><strong>Output:</strong></p><img alt="Image Processing Using Machine Learning" src="https://images.tpointtech.com/tutorial/machine-learning/images/image-processing-using-machine-learning21.png"/><br/><div class="codeblock"><textarea class="java" name="code">plt.figure(figsize=(12,6))
