plt.yticks([])
</textarea></div><p><strong>Output:</strong></p><img alt="Image Processing Using Machine Learning" src="https://images.tpointtech.com/tutorial/machine-learning/images/image-processing-using-machine-learning25.png"/><br/><div class="codeblock"><textarea class="java" name="code">#Setting all values above otsu's threshold as 0 in the matrix and in this image matrix setting all values above 0 as 1 
plt.figure(figsize=(12,6))
canny_conv1=np.where(np.where(canny_mask_smooth&gt;canny_mask_smooth_thresh,0,canny_mask_smooth)&gt;0,1,0)
plt.imshow(canny_conv1,cmap='gray')
